.file-upload:hover,
.file-upload--dragging {
  border-color: #4a90d9;
  background-color: #f0f7ff;
}

.file-upload__input {
  display: none;
}

.file-upload__text {
  margin: 0;
  color: #666;
  font-size: 14px;
}

.file-upload-divider {
  display: flex;
  align-items: center;
  width: 100%;
  margin: 12px 0;
}

.file-upload-divider::before,
.file-upload-divider::after {
  content: '';
  flex: 1;
  border-bottom: 1px solid #ddd;
}

.file-upload-divider span {
  padding: 0 12px;
  color: #999;
  font-size: 13px;
}

