file.content:
.query-editor {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.query-editor__textarea {
  font-family: 'Courier New', Courier, monospace;
  font-size: 14px;
  padding: 12px;
  border: 1px solid #ddd;
  border-radius: 6px;
  resize: vertical;
  outline: none;
  line-height: 1.5;
}

.query-editor__textarea:focus {
  border-color: #4a90d9;
  box-shadow: 0 0 0 2px rgba(74, 144, 217, 0.2);
}

.query-editor__actions {
  display: flex;
  justify-content: flex-end;
}

.query-editor__run-btn {
  padding: 8px 20px;
  background: #4a90d9;
  color: white;
  border: none;
  border-radius: 6px;
  font-size: 14px;
  cursor: pointer;
  transition: background 0.2s;
}

.query-editor__run-btn:hover:not(:disabled) {
  background: #357abd;
}

.query-editor__run-btn:disabled {
  opacity: 0.5;
  cursor: not-allowed;
}

