.results-table__table {
  width: 100%;
  border-collapse: collapse;
  font-size: 13px;
}

.results-table__table th,
.results-table__table td {
  padding: 8px 12px;
  text-align: left;
  border-bottom: 1px solid #eee;
  white-space: nowrap;
}

.results-table__table th {
  background: #f5f5f5;
  font-weight: 600;
  position: sticky;
  top: 0;
  padding: 4px;
  vertical-align: top;
}

.results-table__col-header {
  display: flex;
  align-items: center;
  width: 100%;
  padding: 4px 8px;
  background: none;
  border: none;
  font: inherit;
  font-weight: 600;
  cursor: pointer;
  border-radius: 3px;
  white-space: nowrap;
}

.results-table__col-header:hover {
  background: #e8e8e8;
}

.results-table__sort-icon {
  color: #999;
  font-size: 12px;
  flex-shrink: 0;
}

.results-table__sort-icon--active {
  color: #4a90d9;
}

.results-table__col-filter {
  display: block;
  width: calc(100% - 8px);
  margin: 4px auto 2px;
  padding: 3px 6px;
  font-size: 11px;
  border: 1px solid #ddd;
  border-radius: 3px;
  outline: none;
}

.results-table__col-filter:focus {
  border-color: #4a90d9;
  box-shadow: 0 0 0 1px rgba(74, 144, 217, 0.2);
}

.results-table__table tbody tr:hover {
  background: #f9f9f9;
}

